import { NgFor, NgIf, NgTemplateOutlet } from '@angular/common';
import { ChangeDetectionStrategy, Component, Input, ViewEncapsulation } from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QCheckboxComponent } from '@questrade/allspark-angular-components/checkbox';
import { QIconComponent } from '@questrade/allspark-angular-components/icon';
import { QSkeletonComponent } from '@questrade/allspark-angular-components/skeleton';
import { QSpinnerComponent } from '@questrade/allspark-angular-components/spinner';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { QDropmenuComponent } from '../dropmenu.component';
import { QDropmenuOption } from '../types/dropmenu-option.interface';

@Component({
  selector: 'q-dropmenu-multiselect',
  templateUrl: './dropmenu-multiselect.component.html',
  styleUrls: [
    './../dropmenu.component.scss',
    './../dropmenu-option/dropmenu-option.component.scss',
  ],
  imports: [
    NgIf,
    NgFor,
    NgTemplateOutlet,
    QCheckboxComponent,
    QIconComponent,
    TranslocoModule,
    QSpinnerComponent,
    QSkeletonComponent,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QDropmenuMultiSelectComponent<T> extends QDropmenuComponent<T> {
  @Input() label = 'Items selected {}';

  @Input() override set value(value: T[]) {
    this._value = value;
    if (this._value) {
      this._calculateMultiSelection();
    }
  }
  override get value(): T[] {
    return this._value;
  }

  _selectedOptions: QDropmenuOption<T>[] = [];
  override _value: T[] = [];
  private _isLastFocused = false;

  _onFocus(isLast: boolean): void {
    this._isLastFocused = isLast;
  }

  _onTabKeydown(): void {
    if (this._isLastFocused) this.close();
  }

  override _handleKeyManagerTabOut(): void {
    return;
  }

  isOptionSelected(option: QDropmenuOption<T>): boolean {
    return this.value.includes(option.value);
  }

  _onOptionClick(option: QDropmenuOption<T>): void {
    this._onMultiSelectChange(option);
  }

  get displayValue(): string {
    return this.label.replace('{}', `(${this.value?.length})`);
  }

  private _onMultiSelectChange(option: QDropmenuOption<T>): void {
    if (!this.isOptionSelected(option)) {
      this.value.push(option.value);
    } else {
      this.value = this.value.filter((value) => value !== option.value);
    }

    this._calculateMultiSelection();

    this.valueChange.emit(this._selectedOptions);
  }

  private _calculateMultiSelection(): void {
    this._selectedOptions = this._options.filter((option) => this.value.includes(option.value));
  }
}
