import { Highlightable, ListKeyManagerOption } from '@angular/cdk/a11y';
import { hasModifierKey } from '@angular/cdk/keycodes';
import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  HostBinding,
  HostListener,
  inject,
  Input,
  OnInit,
  Output,
  Renderer2,
  TemplateRef,
  ViewEncapsulation,
} from '@angular/core';
import { QTextHighlightDirective } from '@questrade/allspark-angular-components/core/directives';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { check } from '@questrade/allspark-icons/icons';
import { QDropmenuComponent } from '../dropmenu.component';
import { QDropmenuOptionSelectionChange } from '../types/dropmenu-option-selection-change.interface';

let _uniqueIdCounter = 0;

@Component({
  selector: 'q-dropmenu-option',
  templateUrl: './dropmenu-option.component.html',
  styleUrl: 'dropmenu-option.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgIf, NgTemplateOutlet, QIconComponent, QTextHighlightDirective],
})
export class QDropmenuOptionComponent<T> implements OnInit, ListKeyManagerOption, Highlightable {
  @Output() readonly selectionChange = new EventEmitter<QDropmenuOptionSelectionChange<T>>();

  @Input() value: T | null = null;
  @Input() label = '';
  @Input() subLabel = '';
  @Input() icon = '';
  @Input() index: number | null = null;
  @Input() textToHighlight = '';
  @Input() optionTemplate: TemplateRef<unknown> | null = null;
  @Input({ transform: booleanAttribute }) highlightCaseSensitive = false;
  @Input({ transform: booleanAttribute }) useOverlay = true;
  @Input({ transform: booleanAttribute }) @HostBinding('attr.aria-disabled') disabled = false;

  @HostBinding('attr.role') _role = 'option';
  @HostBinding('attr.id') id = `q-dropmenu-option-${_uniqueIdCounter++}`;
  @HostBinding('attr.aria-selected') selected = false;
  @HostBinding('attr.data-qt') _dataQt = this.id;

  @HostBinding('class') get _hostClasses(): string {
    return [
      'q-dropmenu-option',
      `q-dropmenu-option-density-${this._dropmenu.density}`,
      this.disabled && 'q-dropmenu-option-disabled',
      this.selected && !this._dropmenu.disableSelectionTracking && 'q-dropmenu-option-selected',
    ]
      .filter(Boolean)
      .join(' ');
  }

  @HostListener('click') _onClick = (): void => this.selectViaInteraction();
  @HostListener('keydown', ['$event']) onKeyDown = (event: KeyboardEvent): void =>
    this.handleKeydown(event);

  active = false;
  readonly _dropmenu = inject(QDropmenuComponent);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _renderer = inject(Renderer2);

  ngOnInit(): void {
    this._iconRegistry.registerIcon(check);
  }

  select(emitEvent = true): void {
    if (this.selected) return;

    this.selected = true;

    if (emitEvent) {
      this._emitSelectionChangeEvent();
    }
  }

  deselect(emitEvent = true): void {
    if (!this.selected) return;

    this.selected = false;

    if (emitEvent) {
      this._emitSelectionChangeEvent();
    }
  }

  selectViaInteraction(): void {
    if (this.disabled) return;

    this.selected = true;
    this._emitSelectionChangeEvent(true);
  }

  /**
   * Implemented as a part of `Highlightable`.
   */
  setActiveStyles(): void {
    if (this.active) return;

    this.active = true;
    this._renderer.addClass(this.getHostElement(), 'q-dropmenu-option-active');
    this._dropmenu.scrollOptionIntoView(this, 'nearest');
  }

  /**
   * Implemented as a part of `Highlightable`.
   */
  setInactiveStyles(): void {
    if (!this.active) return;

    this.active = false;
    this._renderer.removeClass(this.getHostElement(), 'q-dropmenu-option-active');
  }

  /** Used internally by the ActiveDescendantKeyManager.withTypeAhead when determining
   *  whether the option should be focused.
   */
  getLabel(): string {
    return this.label || this.subLabel;
  }

  getHostElement(): HTMLElement {
    return this._elementRef.nativeElement;
  }

  handleKeydown(event: KeyboardEvent): void {
    if ([ENTER, SPACE].includes(event.code) && !hasModifierKey(event)) {
      this.selectViaInteraction();

      event.preventDefault();
    }
  }

  private _emitSelectionChangeEvent(isUserInput = false): void {
    this.selectionChange.emit({ source: this, isUserInput });
  }
}
