import { ActiveDescendantKeyManager, FocusMonitor } from '@angular/cdk/a11y';
import { SelectionChange, SelectionModel } from '@angular/cdk/collections';
import { hasModifierKey } from '@angular/cdk/keycodes';
import { CdkOverlayOrigin } from '@angular/cdk/overlay';
import { NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  computed,
  effect,
  ElementRef,
  EventEmitter,
  HostBinding,
  inject,
  Input,
  model,
  numberAttribute,
  OnInit,
  Output,
  QueryList,
  Renderer2,
  signal,
  TemplateRef,
  ViewChildren,
  ViewEncapsulation,
  DOCUMENT,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import {
  ENTER,
  injectDestroy,
  isPresent,
  SPACE,
  UP_ARROW,
} from '@questrade/allspark-angular-components/core/utils';
import { QDividerComponent } from '@questrade/allspark-angular-components/divider';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import {
  QOverlayPositionX,
  QOverlayPositionY,
} from '@questrade/allspark-angular-components/overlay';
import {
  QPopoverDirective,
  QPopoverPlacement,
} from '@questrade/allspark-angular-components/popover';
import { QSkeletonComponent } from '@questrade/allspark-angular-components/skeleton';
import { QSpinnerComponent } from '@questrade/allspark-angular-components/spinner';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { search } from '@questrade/allspark-icons/icons';
import { startWith, takeUntil } from 'rxjs';
import { QDropmenuOptionComponent } from './dropmenu-option/dropmenu-option.component';
import { QDropmenuOriginDirective } from './dropmenu-origin.directive';
import { QDropmenuDensity } from './types/dropmenu-density.type';
import { QDropmenuLoadingVariant } from './types/dropmenu-loading-variant.type';
import { QDropmenuOptionSelectionChange } from './types/dropmenu-option-selection-change.interface';
import { QDropmenuOption } from './types/dropmenu-option.interface';
import { QDropmenuSelectionChange } from './types/dropmenu-selection-change.interface';

let _uniqueIdCounter = 0;

// TODO: Remove this once the overlay related features are removed.
const OVERLAY_POSITION_PLACEMENT_MAP: Record<string, QPopoverPlacement> = {
  'above-start': 'top-start',
  'above-end': 'top-end',
  'above-right': 'right-start',
  'above-left': 'left-start',
  'above-center': 'top',
  'below-right': 'right-end',
  'below-start': 'bottom-start',
  'below-end': 'bottom-end',
  'below-left': 'left-end',
  'below-center': 'bottom',
};

@Component({
  selector: 'q-dropmenu',
  templateUrl: './dropmenu.component.html',
  styleUrl: 'dropmenu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [
    NgTemplateOutlet,
    TranslocoModule,
    QIconComponent,
    QSpinnerComponent,
    QSkeletonComponent,
    QDropmenuOptionComponent,
    QDividerComponent,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  hostDirectives: [
    {
      directive: QPopoverDirective,
      inputs: ['qPopoverPlacement: placement', 'qPopoverOffset: offset'],
    },
  ],
  host: {
    '[attr.popover]': '_popover()',
  },
})
export class QDropmenuComponent<T> implements OnInit, AfterViewInit {
  @Output() readonly selectionChange = new EventEmitter<QDropmenuSelectionChange<T>>();
  @Output() readonly valueChange = new EventEmitter<QDropmenuOption<T> | QDropmenuOption<T>[]>();
  @Output() readonly opened = new EventEmitter<void>();
  @Output() readonly closed = new EventEmitter<void>();

  backdropEnabled = model<boolean>(true);
  fitTriggerWidth = model<boolean>(false);

  @Input() density: QDropmenuDensity = 'default';
  @Input({ transform: booleanAttribute }) highlightCaseSensitive = false;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input({ transform: booleanAttribute }) disableSelectionTracking = false;
  @Input() textToHighlight = '';
  @Input() loadingVariant: QDropmenuLoadingVariant = 'spinner';
  @Input() loadingSkeletonTemplate: TemplateRef<unknown> | null = null;
  @Input() footerMessage = '';
  @Input() footerTemplate: TemplateRef<unknown> | null = null;
  @Input() emptyStateTemplate: TemplateRef<unknown> | null = null;
  @Input() optionTemplate: TemplateRef<unknown> | null = null;
  @Input() groupLabelTemplate: TemplateRef<unknown> | null = null;
  /**
   * @internal
   * This input is used internally for rendering the phone-number search header.
   */
  @Input() headerTemplate: TemplateRef<unknown> | null = null;
  @Input('aria-label') ariaLabel = '';
  @Input('aria-labelledby') ariaLabelledby = '';
  @Input() id = `q-dropmenu-${_uniqueIdCounter++}`;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-dropmenu';

  /**
   * `CdkOverlayOrigin` directive usage is deprecated. Use `qDropmenuOrigin` directive instead.
   */
  @Input() get dropmenuTrigger(): CdkOverlayOrigin | QDropmenuOriginDirective | null {
    return this._dropmenuTrigger;
  }
  set dropmenuTrigger(value: CdkOverlayOrigin | QDropmenuOriginDirective | null) {
    this._dropmenuTrigger = value;
    this._popoverDirective.setPopoverTriggerElement(this.dropmenuTrigger?.elementRef.nativeElement);
  }

  @Input() get groupBy(): string | ((option: QDropmenuOption<T>) => unknown) | null {
    return this._groupBy;
  }
  set groupBy(value: string | ((option: QDropmenuOption<T>) => unknown) | null) {
    this._groupBy = value;

    if (this.options) {
      this._handleGroupedOptions(this.options);
    }
  }

  @Input() get groupLabel():
    | string
    | ((groupKey: unknown, options: QDropmenuOption<T>[]) => string | null)
    | Record<string, string>
    | null {
    return this._groupLabel;
  }
  set groupLabel(
    value:
      | string
      | ((groupKey: unknown, options: QDropmenuOption<T>[]) => string | null)
      | Record<string, string>
      | null,
  ) {
    this._groupLabel = value;

    if (this.groupBy && this.options) {
      this._handleGroupedOptions(this.options);
    }
  }

  @Input() get options(): QDropmenuOption<T>[] {
    return this._options;
  }
  set options(value: QDropmenuOption<T>[]) {
    if (this.groupBy) {
      this._handleGroupedOptions(value);
    } else {
      this._options = value;
    }
  }

  @Input() get value(): T | T[] | null {
    return this._value;
  }
  set value(value: T | T[] | null) {
    if (value === this._value) return;

    this._value = value;
  }

  /**
   * @deprecated Use `--awds-dropmenu-container-min-width` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: numberAttribute }) get minWidth(): number {
    return this._elementRef.nativeElement.style.getPropertyValue(
      '--awds-dropmenu-container-min-width',
    );
  }
  set minWidth(value: number) {
    this._elementRef.nativeElement.style.setProperty(
      '--awds-dropmenu-container-min-width',
      `${value}px`,
    );
  }

  /**
   * @deprecated Use `--awds-dropmenu-container-min-height` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: numberAttribute }) get minHeight(): number {
    return this._elementRef.nativeElement.style.getPropertyValue(
      '--awds-dropmenu-container-min-height',
    );
  }
  set minHeight(value: number) {
    this._elementRef.nativeElement.style.setProperty(
      '--awds-dropmenu-container-min-height',
      `${value}px`,
    );
  }

  /**
   * @deprecated Use `offset` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: numberAttribute }) get offsetY(): number {
    return this._popoverDirective.offset;
  }
  set offsetY(value: number) {
    this._popoverDirective.offset = value;
  }

  /**
   * @deprecated Use `offset` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: numberAttribute }) get offsetX(): number {
    return this._popoverDirective.offset;
  }
  set offsetX(value: number) {
    this._popoverDirective.offset = value;
  }

  /**
   * @deprecated Use `placement` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input() get xPosition(): QOverlayPositionX {
    return this._xPosition;
  }
  set xPosition(value: QOverlayPositionX) {
    this._xPosition = value;
    this._popoverDirective.placement =
      OVERLAY_POSITION_PLACEMENT_MAP[`${this.yPosition}-${this._xPosition}`];
  }

  /**
   * @deprecated Use `placement` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input() get yPosition(): QOverlayPositionY {
    return this._yPosition;
  }
  set yPosition(value: QOverlayPositionY) {
    this._yPosition = value;
    this._popoverDirective.placement =
      OVERLAY_POSITION_PLACEMENT_MAP[`${this._yPosition}-${this._xPosition}`];
  }

  /**
   * @deprecated Use `fitTriggerWidth` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: booleanAttribute }) get fitOverlayWidth(): boolean {
    return this.fitTriggerWidth();
  }
  set fitOverlayWidth(value: boolean) {
    this.fitTriggerWidth.set(value);
  }

  /**
   * @deprecated There's no replacement for this.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: booleanAttribute }) get useOverlay(): boolean {
    return this._useOverlay();
  }
  set useOverlay(value: boolean) {
    this._useOverlay.set(value);
  }

  /**
   * @deprecated Use `backdropEnabled` instead.
   * @breaking-change First major after 25 Feb 2026
   */
  @Input({ transform: booleanAttribute }) get overlayHasBackdrop(): boolean {
    return this.backdropEnabled();
  }
  set overlayHasBackdrop(value: boolean) {
    this.backdropEnabled.set(value);
  }

  @ViewChildren(QDropmenuOptionComponent) optionsQuery!: QueryList<QDropmenuOptionComponent<T>>;

  @HostBinding('attr.tabindex') _tabIndex = -1;
  @HostBinding('class') _hostClass = 'q-dropmenu';

  _popover = computed(this._computerPopover.bind(this));
  _groupedOptions: { groupLabel: string | null; options: QDropmenuOption<T>[] }[] = [];
  _options: QDropmenuOption<T>[] = [];
  _value: T | T[] | null = null;
  _withTypeahead = true;
  _selectKeys = [ENTER, SPACE];
  _groupBy: string | ((option: QDropmenuOption<T>) => unknown) | null = null;
  _groupLabel:
    | string
    | ((groupKey: unknown, options: QDropmenuOption<T>[]) => string | null)
    | Record<string, string>
    | null = null;
  isOpened = false;

  private _useOverlay = signal(true);
  private _xPosition: QOverlayPositionX = 'start';
  private _yPosition: QOverlayPositionY = 'below';
  private _dropmenuTrigger: CdkOverlayOrigin | QDropmenuOriginDirective | null = null;
  private _isKeyboardNavigation = false;
  private _selectionModel = new SelectionModel<QDropmenuOptionComponent<T>>();
  private _keyManager: ActiveDescendantKeyManager<QDropmenuOptionComponent<T>> | null = null;
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _document = inject(DOCUMENT);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _destroy$ = injectDestroy();
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _renderer = inject(Renderer2);
  private readonly _elementRef = inject(ElementRef);
  private readonly _popoverDirective = inject(QPopoverDirective, { host: true });

  constructor() {
    effect(() => {
      this._fitContainerToTrigger();
    });

    this._popoverDirective.placement = 'bottom-start';
  }

  ngOnInit(): void {
    this._iconRegistry.registerIcons([search]);
    this._handleCleanups();
  }

  ngAfterViewInit(): void {
    this._setKeyManager();
    this._handleKeyManagerTabOut();
    this._setTriggerStaticArias();
    this._updateTriggerAriaControls();
    this._handleTriggerDynamicArias();
    this._setKeydownListener();
    this._handleSelectionModelChange();
    this._handleOptionsChange();
    this._monitorKeyboardNavigation();
    this._updateTriggerAriaExpanded(this.isOpened);
    this._handlePopoverOpened();
    this._handlePopoverClosed();
  }

  open(): void {
    if (this.isOpened) return;

    this._fitContainerToTrigger();
    this._elementRef.nativeElement.showPopover({
      source: this.dropmenuTrigger?.elementRef.nativeElement,
    });
    this._initializeSelection();
    this._highlightCorrectOption();
    this._scrollOptionIntoView(this._keyManager?.activeItemIndex || 0);
    this._cdr.markForCheck();
  }

  close(): void {
    this._elementRef.nativeElement.hidePopover();
  }

  /**
   * @param force A boolean, which causes toggle to behave like open or close.
   * If set to true, the dropmenu is opened if it was initially closed. If it was initially opened, nothing happens.
   * If set to false, the dropmenu is closed if it was initially opened. If it was initially closed, nothing happens.
   */
  toggle(force?: boolean): void {
    this._elementRef.nativeElement.togglePopover({
      force: force,
      source: this.dropmenuTrigger?.elementRef.nativeElement,
    });
  }

  _getAriaActiveDescendant(): string {
    if (this.isOpened && this._keyManager && this._keyManager.activeItem) {
      return this._keyManager.activeItem.id;
    }

    return '';
  }

  _handleKeydown = (event: KeyboardEvent): void => {
    if (!this.isOpened) return;

    if (!this._withTypeahead) {
      const isCharacterKey = !!event.key && event.key.length === 1 && !hasModifierKey(event);
      if (isCharacterKey) return;
    }

    this._handleOpenKeydown(event);
  };

  _onOptionSelectionChange(event: QDropmenuOptionSelectionChange<T>): void {
    this._onSelect(event.source, event.isUserInput);

    if (event.isUserInput && this.isOpened) {
      this.close();
    }
  }

  _trackOptionByFn(_index: number, displayOption: QDropmenuOption<T>): string | number {
    return displayOption.trackById ?? _index;
  }

  _getGlobalIndex(groupIndex: number, optionIndex: number): number {
    let cumulativeIndex = 0;

    for (let i = 0; i < groupIndex; i++) {
      cumulativeIndex += this._groupedOptions[i].options.length;
    }

    return cumulativeIndex + optionIndex;
  }

  _getTriggerHostElement(): HTMLElement | null {
    return this.dropmenuTrigger?.elementRef.nativeElement;
  }

  _getDropmenuHostElement(): HTMLElement {
    return this._elementRef.nativeElement;
  }

  resetActiveAfterOptionsChange(): void {
    if (!this._keyManager) return;

    const optionsCount = this.optionsQuery.length;

    if (optionsCount === 0) {
      this._keyManager.updateActiveItem(-1);
      this._updateTriggerAriaActiveDescendant(true);
      this._cdr.markForCheck();
      return;
    }

    const selectedOption = this._selectionModel.selected[0] || null;
    const selectedInList = selectedOption && this.optionsQuery.find((o) => o === selectedOption);

    if (selectedInList && selectedOption) {
      this._keyManager.setActiveItem(selectedOption);
    } else {
      this._keyManager.setActiveItem(this.optionsQuery.first);
    }

    const activeIndex = this._keyManager.activeItemIndex ?? 0;

    this._scrollOptionIntoView(activeIndex);
    this._updateTriggerAriaActiveDescendant(true);
    this._cdr.markForCheck();
  }

  scrollOptionIntoView(
    option: QDropmenuOptionComponent<T>,
    alignment: 'top' | 'nearest' = 'nearest',
  ): void {
    if (!option) return;

    const container = this._elementRef.nativeElement.querySelector('.q-dropmenu-list');
    if (!container) return;

    const optionElement = option.getHostElement();

    const scrollPaddingTop = parseFloat(
      this._document.defaultView?.getComputedStyle(container).scrollPaddingTop || '0',
    );
    const scrollPaddingBottom = parseFloat(
      this._document.defaultView?.getComputedStyle(container).scrollPaddingBottom || '0',
    );

    const containerRect = container.getBoundingClientRect();
    const optionRect = optionElement.getBoundingClientRect();

    const relativeTop = optionRect.top - containerRect.top + container.scrollTop;
    let elementTop = relativeTop - scrollPaddingTop;

    const optionIndex = this.optionsQuery.toArray().indexOf(option);
    const hasGroupLabels = this._hasGroupLabelsBeforeOption(optionIndex);

    if (hasGroupLabels) {
      const currentGroup = this._groupedOptions.find((group) =>
        group.options.some((groupOption) => groupOption.value === option.value),
      );
      const isFirstOptionInGroup = currentGroup?.options[0].value === option.value;

      if (isFirstOptionInGroup) {
        const headerTop = this._getGroupHeaderTop(optionElement, container);
        if (isPresent(headerTop)) {
          elementTop = headerTop - scrollPaddingTop;
        }
      }
    }

    if (alignment === 'top') {
      container.scrollTop = elementTop;
    } else {
      const elementBottom = relativeTop + optionElement.offsetHeight + scrollPaddingBottom;
      const containerTop = container.scrollTop;
      const containerBottom = containerTop + container.offsetHeight;

      if (elementTop < containerTop) {
        container.scrollTop = elementTop;
      } else if (elementBottom > containerBottom) {
        container.scrollTop = Math.max(0, elementBottom - container.offsetHeight);
      }
    }
  }

  _handleKeyManagerTabOut(): void {
    this._keyManager?.tabOut.pipe(takeUntil(this._destroy$)).subscribe(() => {
      if (!this.isOpened) return;

      if (this._keyManager?.activeItem) {
        this._keyManager?.activeItem.selectViaInteraction();
      }

      this.close();
    });
  }

  get selected(): QDropmenuOptionComponent<T> {
    return this._selectionModel.selected[0];
  }

  get empty(): boolean {
    return !this._selectionModel || this._selectionModel.isEmpty();
  }

  get hasFooter(): boolean {
    return (
      (!!this.footerMessage || !!this.footerTemplate) && !this.loading && !!this.options.length
    );
  }

  /**
   * @deprecated There's no replacement for this.
   * @breaking-change First major after 25 Feb 2026
   */
  get overlayMinHeight(): number {
    return !!this.minHeight && !this.loading && !!this.options.length ? this.minHeight : 0;
  }

  /**
   * @deprecated There's no replacement for this.
   * @breaking-change First major after 25 Feb 2026
   */
  get overlayWidth(): number {
    return (this.dropmenuTrigger?.elementRef.nativeElement as HTMLElement)?.clientWidth || 0;
  }

  get triggerValue(): string {
    return this.empty ? '' : this.selected.getLabel();
  }

  private _handlePopoverOpened(): void {
    this._popoverDirective.opened.subscribe(() => {
      this.isOpened = true;
      this._cdr.markForCheck();
      this.opened.emit();

      this._updateTriggerAriaExpanded(true);
      this._updateTriggerAriaActiveDescendant(true);
    });
  }

  private _handlePopoverClosed(): void {
    this._popoverDirective.closed.subscribe(() => {
      this.isOpened = false;
      this._cdr.markForCheck();
      this.closed.emit();
      this._updateTriggerAriaExpanded(false);
      this._updateTriggerAriaActiveDescendant(false);
    });
  }

  private _handleGroupedOptions(options: QDropmenuOption<T>[]): void {
    if (!this.groupBy) return;

    const groups = this._getGroupedOptions(options, this.groupBy);
    this._groupedOptions = groups.map(({ groupKey, options: groupOptions }) => ({
      groupLabel: this._getGroupLabel(groupKey, groupOptions),
      options: groupOptions,
    }));

    this._options = options;
  }

  private _getGroupedOptions(
    options: QDropmenuOption<T>[],
    groupBy: string | ((item: QDropmenuOption<T>) => unknown),
  ): { groupKey: unknown; options: QDropmenuOption<T>[] }[] {
    const groupsMap = new Map<unknown, QDropmenuOption<T>[]>();

    options.forEach((item) => {
      const groupKey = typeof groupBy === 'string' ? item.value[groupBy as keyof T] : groupBy(item);

      if (!groupsMap.has(groupKey)) {
        groupsMap.set(groupKey, []);
      }
      groupsMap.get(groupKey)?.push(item);
    });

    const undefinedGroup = groupsMap.get(undefined);
    if (undefinedGroup) {
      groupsMap.delete(undefined);
    }

    const existingGroups = Array.from(groupsMap.entries()).map(([groupKey, options]) => ({
      groupKey,
      options,
    }));

    return undefinedGroup
      ? [...existingGroups, { groupKey: undefined, options: undefinedGroup }]
      : existingGroups;
  }

  private _getGroupLabel(groupKey: unknown, options: QDropmenuOption<T>[]): string | null {
    if (!this._groupLabel) {
      return null;
    }

    if (typeof this._groupLabel === 'object' && this._groupLabel !== null) {
      const key = groupKey?.toString() || '';
      return this._groupLabel[key] || key;
    }

    if (typeof this._groupLabel === 'string') {
      return (
        (groupKey as Record<string, unknown>)?.[this._groupLabel]?.toString() ||
        groupKey?.toString() ||
        ''
      );
    }

    if (typeof this._groupLabel === 'function') {
      return this._groupLabel(groupKey, options);
    }

    return groupKey?.toString() || '';
  }

  private _handleOpenKeydown(event: KeyboardEvent): void {
    this._isKeyboardNavigation = true;
    const manager = this._keyManager;
    const code = event.code;
    const isTyping = manager?.isTyping();

    if (code === UP_ARROW && event.altKey) {
      event.preventDefault();
      manager?.activeItem?.selectViaInteraction();
      this.close();
    } else if (
      !isTyping &&
      this._selectKeys.includes(code) &&
      manager?.activeItem &&
      !hasModifierKey(event)
    ) {
      event.preventDefault();
      manager.activeItem.selectViaInteraction();
    } else {
      manager?.onKeydown(event);
    }
  }

  private _initializeSelection(): void {
    this._setSelectionByValue(this._value as T | null);
  }

  private _setSelectionByValue(value: T | null): void {
    this.optionsQuery?.forEach((option) => option.setInactiveStyles());
    this._selectionModel.clear();

    const correspondingOption = this._selectOptionByValue(value);

    if (correspondingOption) {
      this._keyManager?.updateActiveItem(correspondingOption);
    } else if (!this.isOpened) {
      this._keyManager?.updateActiveItem(-1);
    }

    this._cdr.detectChanges();
  }

  private _selectOptionByValue(value: T | null): QDropmenuOptionComponent<T> | null {
    const correspondingOption =
      this.optionsQuery.find((option: QDropmenuOptionComponent<T>) => option.value === value) ||
      null;

    if (correspondingOption) {
      this._selectionModel.select(correspondingOption);
    } else if (this.empty) {
      this._selectionModel.clear();
    }

    return correspondingOption;
  }

  private _setKeyManager(): void {
    if (!this.optionsQuery) return;

    this._keyManager = new ActiveDescendantKeyManager<QDropmenuOptionComponent<T>>(
      this.optionsQuery,
    )
      .withHomeAndEnd()
      .withPageUpDown();

    if (this._withTypeahead) {
      this._keyManager.withTypeAhead();
    }
  }

  private _onSelect(option: QDropmenuOptionComponent<T>, isUserInput: boolean): void {
    const wasSelected = this._selectionModel.isSelected(option);

    if (wasSelected !== option.selected) {
      option.selected ? this._selectionModel.select(option) : this._selectionModel.deselect(option);

      this._propagateChanges();
    }

    if (isUserInput) {
      this._keyManager?.setActiveItem(option);
    }
  }

  private _propagateChanges(): void {
    this._value = this.selected.value;
    this.valueChange.emit(this.options.find((option) => option.value === this.value));
    this.selectionChange.emit({ source: this, option: this.selected });
    this._cdr.markForCheck();
  }

  private _highlightCorrectOption(): void {
    if (!this._keyManager || !this._isKeyboardNavigation) return;

    this.empty
      ? this._keyManager.setFirstItemActive()
      : this._keyManager.setActiveItem(this.selected);
  }

  private _getGroupHeaderTop(optionElement: HTMLElement, container: HTMLElement): number | null {
    let currentElement = optionElement.previousElementSibling as HTMLElement | null;
    let headerTop: number | null = null;

    const containerRect = container.getBoundingClientRect();

    while (currentElement) {
      if (
        currentElement.tagName.toLowerCase() === 'q-divider' ||
        currentElement.tagName.toLowerCase() === 'q-dropmenu-option'
      ) {
        break;
      }

      const elementRect = currentElement.getBoundingClientRect();
      headerTop = elementRect.top - containerRect.top + container.scrollTop;
      currentElement = currentElement.previousElementSibling as HTMLElement | null;
    }

    return headerTop;
  }

  private _hasGroupLabelsBeforeOption(optionIndex: number): boolean {
    if (!this.groupBy) return false;

    let currentOptionCount = 0;

    for (const group of this._groupedOptions) {
      if (currentOptionCount > optionIndex) break;

      if (group.groupLabel !== null || this.groupLabelTemplate) {
        return true;
      }

      currentOptionCount += group.options.length;
    }

    return false;
  }

  private _scrollOptionIntoView(index: number): void {
    if (index < 0) return;

    const option = this.optionsQuery.get(index);

    if (!option) return;

    this.scrollOptionIntoView(option, 'top');
  }

  private _handleOptionsChange(): void {
    this.optionsQuery?.changes
      .pipe(startWith(null), takeUntil(this._destroy$))
      .subscribe(() => this._initializeSelection());
  }

  private _handleSelectionModelChange(): void {
    this._selectionModel.changed
      .pipe(takeUntil(this._destroy$))
      .subscribe((event: SelectionChange<QDropmenuOptionComponent<T>>) => {
        event.added.forEach((option) => option.select());
        event.removed.forEach((option) => option.deselect());
      });
  }

  private _handleTriggerDynamicArias(): void {
    this._keyManager?.change
      .pipe(takeUntil(this._destroy$))
      .subscribe(() => this._updateTriggerAriaActiveDescendant());
  }

  private _setTriggerStaticArias(): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;

    this._renderer.setAttribute(trigger, 'role', 'combobox');
    this._renderer.setAttribute(trigger, 'aria-haspopup', 'listbox');
  }

  private _updateTriggerAriaControls(): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;

    this._renderer.setAttribute(trigger, 'aria-controls', this.id);
  }

  private _updateTriggerAriaExpanded(isOpen: boolean): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;

    this._renderer.setAttribute(trigger, 'aria-expanded', isOpen ? 'true' : 'false');
  }

  private _updateTriggerAriaActiveDescendant(isOpen = true): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;

    isOpen
      ? this._renderer.setAttribute(
          trigger,
          'aria-activedescendant',
          this._getAriaActiveDescendant(),
        )
      : this._renderer.removeAttribute(trigger, 'aria-activedescendant');
  }

  private _monitorKeyboardNavigation(): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;

    this._focusMonitor
      .monitor(trigger)
      .pipe(takeUntil(this._destroy$))
      .subscribe((event) => (this._isKeyboardNavigation = event === 'keyboard'));
  }

  private _setKeydownListener(): void {
    const trigger = this._getTriggerHostElement();

    if (!trigger) return;
    trigger.addEventListener('keydown', this._handleKeydown);
  }

  private _handleCleanups(): void {
    const trigger = this._getTriggerHostElement();

    this._destroy$.onDestroy(() => {
      this._keyManager?.destroy();

      if (trigger) {
        this._focusMonitor.stopMonitoring(trigger);
        trigger.removeEventListener('keydown', this._handleKeydown);
      }
    });
  }

  private _computerPopover(): string | null {
    if (!this._useOverlay()) {
      this._popoverDirective._hostClass = '';
      return null;
    }

    return this.backdropEnabled() ? 'auto' : 'manual';
  }

  private _fitContainerToTrigger(): void {
    if (this.fitTriggerWidth()) {
      this._elementRef.nativeElement.style.setProperty(
        '--awds-dropmenu-container-width',
        `${this.dropmenuTrigger?.elementRef.nativeElement.clientWidth}px`,
      );
    } else {
      this._elementRef.nativeElement.style.removeProperty('--awds-dropmenu-container-width');
    }
  }
}
